import Foundation
import RealityKit
import UIKit

/// W4 折纸世界: the card is the first page of a pop-up book. Pages hinge open on the desk, paper-craft pieces
/// (generated by `tools/assets/paper_models.py`: layered mountains, trees, houses, a windmill, a train on its
/// track) pop up one by one, and the room-scale valley — mountains, houses, clouds, the paper sun, trees on a
/// meadow — unfolds from a centre crease around the wearer. Fully immersive behind a cream shell lit by a warm
/// fireplace IBL; the real room turns to paper and folds away (RoomFission).
///
/// Entry (3.2 s, unfold): 0.00–0.20 the page corner lifts · 0.20–0.50 two pages hinge open flat · 0.50–0.85
/// pop-ups rise in sequence (each with a "pop") · 0.55–1.00 room pieces unfold from their crease (scale.x).
/// Exit (2.6 s, fold): pop-ups fold flat in reverse (paper flips) · room pieces fold back to the crease · pages
/// close and the book shrinks back into the card · a puff of paper confetti.
@MainActor
final class PaperValleyWorld: World {
    let descriptor: WorldDescriptor
    let root = Entity()
    private let book = Entity()
    private let leftPage: Entity
    private let rightPage: Entity
    private var popups: [Entity] = []       // desk pop-ups, scale.y animated, in pop order
    private var roomPieces: [Entity] = []   // asset-layer pieces, scale.x animated (unfold from a crease)
    private var train: Entity?
    private var trainCar: Entity?
    private var windmillBlades: Entity?
    private var birds: [(body: Entity, wings: [Entity])] = []
    private var trainAngle: Float = 0
    private var time: Float = 0
    private var popped = 0
    private var rng = WorldKit.RNG(0x9A9E)
    private let confetti = Entity()
    private var rescaledPopups: [Float] = []
    /// Desk track semi-axes: must match TRACK_A / TRACK_B in paper_models.py.
    private let trackA: Float = 0.15, trackB: Float = 0.105

    init(descriptor: WorldDescriptor) {
        self.descriptor = descriptor
        leftPage = Entity()
        rightPage = Entity()
        root.addChild(book)
        book.addChild(leftPage)
        book.addChild(rightPage)
    }

    /// Unlit paper for the procedural pages: inside the shell there is no passthrough light.
    private func paper(_ color: UIColor) -> UnlitMaterial {
        WorldKit.unlit(color, texture: WorldKit.paperTexture())
    }

    /// Clone a generated piece (nil until the library has it; the engine preloads `extraAssets`).
    private func piece(_ name: String, _ engine: WorldEngine) -> Entity? {
        engine.assets.entity(world: descriptor.id, name: name)
    }

    /// The room turns to paper and folds away sheet by sheet (RoomFission).
    func fissionRecipe(ctx: WorldContext) -> RoomFission.Recipe? { RoomFission.paperValley(descriptor) }

    func build(ctx: WorldContext, engine: WorldEngine) {
        let card = ctx.cardPosition
        book.position = SIMD3(card.x, ctx.surfaceY + 0.002, card.z)
        book.orientation = ctx.yaw
        // Pages: 0.30 × 0.42 m each, hinged on the card's centre line (local x = 0).
        for (page, side) in [(leftPage, Float(-1)), (rightPage, Float(1))] {
            page.children.forEach { $0.removeFromParent() }
            let sheet = ModelEntity(mesh: .generatePlane(width: 0.30, depth: 0.42), materials: [paper(descriptor.highlightColor)])
            sheet.position = [side * 0.15, 0, 0]
            page.addChild(sheet)
            page.orientation = simd_quatf(angle: side * -.pi / 2, axis: [0, 0, 1])   // closed: standing up
        }
        for e in popups { e.removeFromParent() }
        popups.removeAll(); rescaledPopups.removeAll()

        // Desk pop-ups (book-local: x right, z toward the wearer). Unit pieces are metres; ×0.14–0.2 on the book.
        func popup(_ name: String, at: SIMD3<Float>, scale: Float, yaw: Float = 0) -> Entity? {
            guard let e = piece(name, engine) else { return nil }
            let holder = Entity()
            holder.position = at
            holder.orientation = simd_quatf(angle: yaw, axis: [0, 1, 0])
            e.scale = SIMD3(repeating: scale)
            holder.addChild(e)
            holder.scale = [1, 0.001, 1]
            book.addChild(holder)
            popups.append(holder)
            return holder
        }
        _ = popup("paper_mountain_a", at: [-0.07, 0, -0.15], scale: 0.14)
        _ = popup("paper_mountain_b", at: [0.13, 0, -0.11], scale: 0.11, yaw: 0.35)
        let treeSpots: [SIMD3<Float>] = [[-0.24, 0, 0.02], [-0.19, 0, 0.07], [-0.14, 0, 0.0], [0.24, 0, 0.09], [0.19, 0, 0.13]]
        for (i, spot) in treeSpots.enumerated() { _ = popup(i % 2 == 0 ? "paper_tree_a" : "paper_tree_b", at: spot, scale: 0.05 + 0.012 * Float(i % 3), yaw: Float(i)) }
        _ = popup("paper_house_a", at: [-0.2, 0, -0.06], scale: 0.055, yaw: 0.5)
        _ = popup("paper_house_b", at: [0.24, 0, -0.02], scale: 0.05, yaw: -0.6)
        if let mill = popup("paper_windmill", at: [0.2, 0, 0.03], scale: 0.12, yaw: -0.3), let blades = piece("paper_windmill_blades", engine) {
            // Blades pivot on their hub (origin) and face +Z; the hub sits near the tower top.
            blades.scale = SIMD3(repeating: 0.12)
            blades.position = [0, 0.11, 0.022]
            mill.children.first?.addChild(blades)
            windmillBlades = blades
        }
        _ = popup("paper_track", at: [0, 0.0005, 0.02], scale: 1)
        // Train: engine + one car following the track ellipse (book-local), appears after the track.
        train?.removeFromParent(); trainCar?.removeFromParent()
        if let engineE = piece("paper_train_engine", engine) {
            engineE.scale = SIMD3(repeating: 0.001)
            book.addChild(engineE)
            train = engineE
        }
        if let carE = piece("paper_train_car", engine) {
            carE.scale = SIMD3(repeating: 0.001)
            book.addChild(carE)
            trainCar = carE
        }
        // Avatar standee.
        if let cg = UIImage(named: "Avatar")?.cgImage, let tex = try? TextureResource(image: cg, withName: "paper-avatar", options: .init(semantic: .color)) {
            let standee = ModelEntity(mesh: .generatePlane(width: 0.07, height: 0.07), materials: [WorldKit.unlit(.white, texture: tex)])
            standee.position.y = 0.035
            let holder = Entity()
            holder.position = [0.0, 0, 0.15]
            holder.addChild(standee)
            holder.scale = [1, 0.001, 1]
            book.addChild(holder)
            popups.append(holder)
        }

        // Room pieces: everything the descriptor placed (mountains, houses, clouds, sun, trees) unfolds from its crease.
        roomPieces.removeAll()
        if let assets = root.findEntity(named: "assets") {
            for child in assets.children where child.name != "fog" {
                // The meadow disc (paper_ground) stays flat; everything else folds.
                if let placed = child.children.first?.name, placed.contains("ground") { continue }
                if (child as? ModelEntity) == nil, child.children.isEmpty { continue }
                child.scale.x = 0.001
                roomPieces.append(child)
            }
        }
        // Birds: body + two hinged wings (the wing extends +X from its hinge; mirrored copy for the other side).
        for b in birds { b.body.removeFromParent() }
        birds.removeAll()
        let origin = ctx.origin, f = ctx.forward, r = ctx.right
        for i in 0..<3 {
            guard let body = piece("paper_bird_body", engine), let wingL = piece("paper_bird_wing", engine), let wingR = piece("paper_bird_wing", engine) else { break }
            wingR.scale.x = -1
            body.addChild(wingL); body.addChild(wingR)
            body.scale = SIMD3(repeating: 0.9)
            body.position = origin + f * (2.4 + Float(i) * 0.5) + r * (Float(i) * 0.6 - 0.8) + [0, 2.15 + Float(i) * 0.12, 0]
            body.orientation = ctx.yaw * simd_quatf(angle: .pi + Float(i) * 0.2, axis: [0, 1, 0])
            body.components.set(FloatComponent(basePosition: body.position, axis: simd_normalize(r * 0.7 + f * 0.3), amplitude: 0.8, period: 12, phase: Float(i) * 0.7))
            body.components.set(OpacityComponent(opacity: 0))
            root.addChild(body)
            birds.append((body, [wingL, wingR]))
        }
        // Confetti for the fold-away.
        confetti.position = book.position + [0, 0.05, 0]
        var c = ParticleEmitterComponent()
        c.emitterShape = .sphere
        c.emitterShapeSize = [0.05, 0.02, 0.05]
        c.birthLocation = .volume
        c.speed = 0.5; c.speedVariation = 0.3
        c.mainEmitter.image = FXTextures.shared.coreDisc
        c.mainEmitter.blendMode = .alpha
        c.mainEmitter.birthRate = 0
        c.mainEmitter.lifeSpan = 1.6
        c.mainEmitter.size = 0.012; c.mainEmitter.sizeVariation = 0.006
        c.mainEmitter.acceleration = [0, -0.9, 0]
        c.mainEmitter.spreadingAngle = .pi / 2
        c.mainEmitter.angularSpeed = 4
        c.mainEmitter.opacityCurve = .linearFadeOut
        c.mainEmitter.isLightingEnabled = false
        c.mainEmitter.color = .evolving(start: .random(a: descriptor.highlightColor, b: descriptor.accentColor), end: .single(descriptor.primaryColor.withAlphaComponent(0)))
        c.isEmitting = false
        confetti.components.set(c)
        root.addChild(confetti)
        popped = 0
        engine.shell.setColor(descriptor.shellColor)
    }

    func applyQuality(_ tier: WorldQuality) {
        for (i, b) in birds.enumerated() { b.body.isEnabled = tier > .low || i == 0 }
    }

    private func pop(_ n: Int) {
        while popped < min(n, popups.count) {
            let e = popups[popped]
            e.components.set(TweenComponent(scale: (from: [1, 0.001, 1], to: [1, 1, 1]), duration: 0.45, easing: .easeOutBack))
            FXAudio.shared.play(.pop, on: e)
            popped += 1
        }
    }

    func entry(progress p: Float, dt: Float, ctx: WorldContext, engine: WorldEngine) {
        time += dt
        // Pages: closed (±90°) → flat (0) over 0.2–0.5 with a paper flip at the start.
        let open = max(0, min(1, (p - 0.2) / 0.3))
        let eased = 1 - pow(1 - open, 3)
        leftPage.orientation = simd_quatf(angle: -(.pi / 2) * (1 - eased), axis: [0, 0, 1])
        rightPage.orientation = simd_quatf(angle: (.pi / 2) * (1 - eased), axis: [0, 0, 1])
        if p >= 0.2 && p < 0.215 { FXAudio.shared.play(.paperFlip, on: root) }
        // Pop-ups between 0.5 and 0.85.
        let stage = Int(max(0, (p - 0.5) / 0.35) * Float(popups.count + 1))
        pop(stage)
        if p > 0.85, let train, train.scale.x < 0.5 {
            train.components.set(TweenComponent(scale: (from: [0.001, 0.001, 0.001], to: [1, 1, 1]), duration: 0.35, easing: .easeOutBack))
            trainCar?.components.set(TweenComponent(scale: (from: [0.001, 0.001, 0.001], to: [1, 1, 1]), delay: 0.08, duration: 0.35, easing: .easeOutBack))
        }
        // Room pieces unfold from the crease 0.55–1.0 (staggered by index).
        for (i, piece) in roomPieces.enumerated() {
            let k = max(0, min(1, (p - 0.55 - Float(i % 12) * 0.03) / 0.3))
            piece.scale.x = max(0.001, 1 - pow(1 - k, 3))
        }
        for b in birds { b.body.components.set(OpacityComponent(opacity: max(0, min(1, (p - 0.8) / 0.2)))) }
        engine.shell.set(opacity: descriptor.immersion.shellOpacity * max(0, (p - 0.55) / 0.45))
        animate(dt: dt)
    }

    private func animate(dt: Float) {
        trainAngle += dt * 0.9
        // Engine on the ellipse, car trailing by an arc offset; pieces point along +X, so orient along the tangent.
        func place(_ e: Entity?, at angle: Float) {
            guard let e else { return }
            let x = cos(angle) * trackA, z = sin(angle) * trackB
            e.position = [x, 0.001, z + 0.02]
            let tx = -sin(angle) * trackA, tz = cos(angle) * trackB
            e.orientation = simd_quatf(angle: -atan2(tz, tx), axis: [0, 1, 0])
        }
        place(train, at: trainAngle)
        place(trainCar, at: trainAngle - 0.42)
        windmillBlades?.orientation = simd_quatf(angle: time * 1.6, axis: [0, 0, 1])
        for (i, bird) in birds.enumerated() {
            let flap = sin(time * 6 + Float(i)) * 0.55
            for (j, wing) in bird.wings.enumerated() {
                wing.orientation = simd_quatf(angle: (j == 0 ? 1 : -1) * flap, axis: [0, 0, 1])
            }
        }
    }

    func inside(dt: Float, ctx: WorldContext, engine: WorldEngine) {
        time += dt
        animate(dt: dt)
        engine.shell.set(opacity: descriptor.immersion.shellOpacity)
    }

    func exit(progress p: Float, dt: Float, ctx: WorldContext, engine: WorldEngine) {
        time += dt
        animate(dt: dt * (1 - p))
        // Pop-ups fold flat in reverse (0–0.45), room pieces fold (0.1–0.6), pages close (0.45–0.8), book shrinks (0.8–1).
        for (i, e) in popups.reversed().enumerated() {
            let k = max(0, min(1, (p - Float(i) * 0.04) / 0.2))
            if k > 0 && k < 1 && e.components[TweenComponent.self] != nil { e.components.remove(TweenComponent.self) }
            if k > 0 { e.scale.y = max(0.001, 1 - k) }
            if k > 0 && k < 0.1 { FXAudio.shared.play(.paperFlip, on: e) }
        }
        let trainK = max(0.001, 1 - min(1, p / 0.2))
        train?.scale = SIMD3(repeating: trainK)
        trainCar?.scale = SIMD3(repeating: trainK)
        for (i, piece) in roomPieces.enumerated() {
            let k = max(0, min(1, (p - 0.1 - Float(i % 12) * 0.03) / 0.3))
            piece.scale.x = max(0.001, 1 - k)
        }
        for b in birds { b.body.components.set(OpacityComponent(opacity: max(0, 1 - p / 0.3))) }
        let close = max(0, min(1, (p - 0.45) / 0.35))
        leftPage.orientation = simd_quatf(angle: -(.pi / 2) * close, axis: [0, 0, 1])
        rightPage.orientation = simd_quatf(angle: (.pi / 2) * close, axis: [0, 0, 1])
        if p >= 0.45 && p < 0.465 { FXAudio.shared.play(.paperFlip, on: root) }
        let shrink = max(0, min(1, (p - 0.8) / 0.2))
        book.scale = SIMD3(repeating: max(0.001, 1 - shrink))
        if p >= 0.8 && p < 0.83, var c = confetti.components[ParticleEmitterComponent.self], !c.isEmitting {
            c.isEmitting = true
            c.mainEmitter.birthRate = 0
            c.burstCount = 60
            c.burst()
            confetti.components.set(c)
        }
        engine.shell.set(opacity: descriptor.immersion.shellOpacity)
    }

    func teardown() {}
}
